import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { exportCsv } from '../src/export.js';

test('exportCsv returns header line', () => {
  const r = exportCsv([]);
  assert.equal(r.ok, true);
  assert(r.value.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv includes header and ends with newline', () => {
  const r = exportCsv([]);
  assert.equal(r.ok, true);
  assert.equal(r.value, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv with single issued invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert.equal(lines.length, 2);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert(lines[1].includes(issued.value.number));
  assert(lines[1].includes('Alice'));
  assert(lines[1].includes('issued'));
});

test('exportCsv with multiple invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 3, discountPercent: 0 }],
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  const r = exportCsv([issued1.value, issued2.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert.equal(lines.length, 3);
  assert(lines[1].includes(issued1.value.number));
  assert(lines[2].includes(issued2.value.number));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  // Check that amounts have 2 decimals
  const lines = r.value.trim().split('\n');
  const dataLine = lines[1];
  // Amounts should be formatted like 50.00, 1.05, etc.
  const parts = dataLine.split(',');
  const subtotal = parts[5];
  const discount = parts[6];
  const vat = parts[7];
  const total = parts[8];
  const due = parts[9];

  // All amounts should have 2 decimal places
  assert(/^\d+\.\d{2}$/.test(subtotal));
  assert(/^\d+\.\d{2}$/.test(discount));
  assert(/^\d+\.\d{2}$/.test(vat));
  assert(/^\d+\.\d{2}$/.test(total));
  assert(/^\d+\.\d{2}$/.test(due));
});

test('exportCsv includes draft invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const r = exportCsv([invResult.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert.equal(lines.length, 2);
  assert(lines[1].includes('draft'));
});

test('exportCsv escapes fields with commas', () => {
  // Create a mock customer lookup that would require escaping
  // For this test, we rely on customer names that might have commas
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  // Verify CSV is valid (header should not have quotes)
  const lines = r.value.trim().split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv returns empty CSV for empty array', () => {
  const r = exportCsv([]);
  assert.equal(r.ok, true);
  const lines = r.value.trim().split('\n');
  assert.equal(lines.length, 1);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes customer name', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert(lines[1].includes('Alice'));
});

test('exportCsv includes all required fields', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  const fields = lines[1].split(',');

  // Should have exactly 10 fields
  assert.equal(fields.length, 10);

  // Verify each field is present
  assert(fields[0]); // number
  assert(fields[1]); // customer
  assert.equal(fields[2], '2026-10-07'); // issueDate
  assert(fields[3]); // dueDate
  assert.equal(fields[4], 'issued'); // status
  assert(fields[5]); // subtotal
  assert(fields[6]); // discount
  assert(fields[7]); // vat
  assert(fields[8]); // total
  assert(fields[9]); // due
});

test('exportCsv with partially paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const partial = recordPayment(issued.value, { amount: 50000, date: '2026-10-08' });
  assert.equal(partial.ok, true);

  const r = exportCsv([partial.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert(lines[1].includes('partially_paid'));
});

test('exportCsv with paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const due = require('../src/payments.js').balanceDue(issued.value);
  const paid = recordPayment(issued.value, { amount: due, date: '2026-10-08' });
  assert.equal(paid.ok, true);

  const r = exportCsv([paid.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert(lines[1].includes('paid'));
  // Due should be 0 for paid invoice
  const fields = lines[1].split(',');
  assert.equal(fields[9], '0.00');
});

test('exportCsv lines end with newline', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  assert(r.value.endsWith('\n'));
});

test('exportCsv with discount', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = exportCsv([issued.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  const fields = lines[1].split(',');
  const discount = parseFloat(fields[6]);

  // Discount should be non-zero
  assert(discount > 0);
});

test('exportCsv maintains invoice order', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: 0 }],
  });
  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DEV-HOUR', qty: 3, discountPercent: 0 }],
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);
  assert.equal(inv3Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(inv3Result.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = exportCsv([issued1.value, issued2.value, issued3.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert.equal(lines[1].includes('2026-10-01'), true);
  assert.equal(lines[2].includes('2026-10-02'), true);
  assert.equal(lines[3].includes('2026-10-03'), true);
});

test('exportCsv with different customers', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  const r = exportCsv([issued1.value, issued2.value]);
  assert.equal(r.ok, true);

  const lines = r.value.trim().split('\n');
  assert(lines[1].includes('Alice'));
  assert(lines[2].includes('Bob'));
});

